function (vars) {
	var g = new GridWidget(vars.element, vars.invoices);
        g.editable = false;
        g.sortable = false;
        g.filterable = false;
        g.pageable = false;
        g.scrollable = false;
        g.groupable = false;
        g.commands.push({ name: "view", icon: "k-i-share", text: "[resource_shortdisplayname[view]]", href: "/Transactions/Invoice?Id=#:Id#" });
        g.columns = [
            { field: "Number", title: "[resource_displayname[number]]" },
            { field: "DueDate", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_displayname[duedate]]" },
            { field: "TaxPoint", type: "date", format: "{0:" + type.dateFormat + "}", title: "[resource_displayname[taxpoint]]" },
            { field: "DebtorState", template: "#:B2B.transactionStates[DebtorState]#", title: "[resource_displayname[debtorstate]]" },
            { field: "FundingState", title: "[resource_displayname[fundingstate]]", template: "#:((FundingState) ? B2B.transactionStates[FundingState]: '')#" }
        ];
        vars.RelatedInvoicesGrid = g;
		return g;
}
